// ================================================================
//            PROVIDED TEST HARNESS -- DO NOT EDIT THIS FILE
// ================================================================
//
// usage: ./task3.out [base] [order] [simd]      (no argument = all three)
//
// Builds M random points with D coordinates each, computes the distance matrix
// once in double precision as the reference, then for every kernel named:
// runs it REPS times, prints the best time and whether the result matches the
// reference. With more than one kernel it also prints the speedups.

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>
#include "kernels.h"

constexpr int M    = 4096;
constexpr int D    = 64;
constexpr int REPS = 3;

static_assert(M % 8 == 0, "M must be a multiple of 8");

using Kernel = void (*)(const float*, int, int, float*);

struct Entry {
    const char* name;
    Kernel f;
    double ms;     // best time, < 0 if not run
    bool correct;
};

static bool matches(const std::vector<float>& out, const std::vector<float>& ref) {
    for (size_t k = 0; k < ref.size(); k++)
        if (std::fabs(out[k] - ref[k]) > 1e-3f * std::fabs(ref[k]) + 1e-4f) return false;
    return true;
}

static void run(Entry& e, const std::vector<float>& P, std::vector<float>& out,
                const std::vector<float>& ref) {
    using clk = std::chrono::steady_clock;
    double best = 1e30;
    for (int r = 0; r < REPS; r++) {
        std::fill(out.begin(), out.end(), 0.0f);
        auto t0 = clk::now();
        e.f(P.data(), M, D, out.data());
        double ms = std::chrono::duration<double, std::milli>(clk::now() - t0).count();
        best = std::min(best, ms);
    }
    e.ms = best;
    e.correct = matches(out, ref);
    std::printf("%-6s %10.1f ms  %s\n", e.name, e.ms, e.correct ? "PASS" : "FAIL (wrong result)");
}

int main(int argc, char** argv) {
    Entry k[] = {{"base", dist_base, -1, false},
                 {"order", dist_order, -1, false},
                 {"simd", dist_simd, -1, false}};

    bool want[3] = {argc == 1, argc == 1, argc == 1};
    for (int a = 1; a < argc; a++) {
        bool known = false;
        for (int n = 0; n < 3; n++)
            if (std::strcmp(argv[a], k[n].name) == 0) want[n] = known = true;
        if (!known) {
            std::fprintf(stderr, "unknown kernel '%s' (use base, order, simd)\n", argv[a]);
            return 1;
        }
    }

    std::vector<float> P((size_t)D * M), out((size_t)M * M), ref((size_t)M * M);

    // fixed pseudo-random points in [0, 1), the same on every run
    uint32_t s = 12345;
    for (auto& v : P) {
        s = s * 1664525u + 1013904223u;
        v = (s >> 8) / 16777216.0f;
    }

    // reference in double precision (not timed)
    for (int i = 0; i < M; i++)
        for (int j = 0; j < M; j++) {
            double a = 0;
            for (int d = 0; d < D; d++) {
                double t = (double)P[d * M + i] - P[d * M + j];
                a += t * t;
            }
            ref[(size_t)i * M + j] = (float)a;
        }

    std::printf("M=%d D=%d, best of %d runs\n", M, D, REPS);
    for (int n = 0; n < 3; n++)
        if (want[n]) run(k[n], P, out, ref);

    Entry &base = k[0], &order = k[1], &simd = k[2];
    if (base.ms > 0 && order.ms > 0) std::printf("speedup order over base  = %.2fx\n", base.ms / order.ms);
    if (order.ms > 0 && simd.ms > 0) std::printf("speedup simd  over order = %.2fx\n", order.ms / simd.ms);
    if (base.ms > 0 && simd.ms > 0)  std::printf("speedup simd  over base  = %.2fx\n", base.ms / simd.ms);

    for (int n = 0; n < 3; n++)
        if (want[n] && !k[n].correct) return 1;
    return 0;
}
